sp_EditarProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarProduto`(\n\n    IN p_idProduto          INT,\n\n    IN p_Nome               VARCHAR(60),\n\n    IN p_Descricao          VARCHAR(120),\n\n    IN p_codProduto         VARCHAR(15),\n\n    IN p_codBarras          VARCHAR(14),\n\n    IN p_precoCusto         DECIMAL(10,2),\n\n    IN p_precoVenda         DECIMAL(10,2),\n\n    IN p_categoriaProduto_id INT,\n\n    IN p_uniMedida_id       INT\n\n)\nBEGIN\n\n    UPDATE Produto SET\n\n        Nome                 = p_Nome,\n\n        Descricao            = p_Descricao,\n\n        codProduto           = p_codProduto,\n\n        codBarras            = p_codBarras,\n\n        precoCusto           = p_precoCusto,\n\n        precoVenda           = p_precoVenda,\n\n        categoriaProduto_id  = p_categoriaProduto_id,\n\n        uniMedida_id         = p_uniMedida_id\n\n    WHERE idProduto = p_idProduto;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
